mapper.select:
SELECT t.*, o.order_no, o.status AS order_status, o.version AS order_version FROM runrun_v2.fulfillment_tasks t JOIN runrun_v2.v2_orders o ON o.id = t.order_id WHERE t.courier_id = #{courierId,jdbcType=BIGINT}
AND t.status = #{status,jdbcType=VARCHAR}
AND (t.created_at,t.id) < (#{afterCreatedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},#{afterId,jdbcType=BIGINT})
ORDER BY t.created_at DESC, t.id DESC LIMIT #{limit,jdbcType=INTEGER}

SELECT o.* FROM runrun_v2.v2_orders o WHERE o.status = 'PENDING_ASSIGNMENT' AND EXISTS ( SELECT 1 FROM runrun_v2.payment_orders p WHERE p.order_id = o.id AND p.purpose = 'ORIGINAL' AND p.status = 'PAID')
AND (o.created_at,o.id) < (#{afterCreatedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},#{afterId,jdbcType=BIGINT})
ORDER BY o.created_at DESC, o.id DESC LIMIT #{limit,jdbcType=INTEGER}
